PRAGMA foreign_keys=ON;
CREATE TABLE licenses(id TEXT PRIMARY KEY,key_hash TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',starts INTEGER NOT NULL,expires INTEGER NOT NULL,max_devices INTEGER NOT NULL CHECK(max_devices BETWEEN 1 AND 100),features TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',is_free INTEGER NOT NULL DEFAULT 0);
CREATE TABLE devices(id TEXT PRIMARY KEY,license_id TEXT REFERENCES licenses(id),spki TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',build TEXT NOT NULL,seen INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '');
CREATE TABLE challenges(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,license_id TEXT NOT NULL,nonce TEXT NOT NULL,build TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE replay(id TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE system_state(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL,minimum_version TEXT NOT NULL,public_limit INTEGER NOT NULL,admin_limit INTEGER NOT NULL);
INSERT INTO system_state VALUES(1,1,'0.2.0',10000,2000);
CREATE TABLE quota(day TEXT NOT NULL,pool TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(day,pool));
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE login_failures(ip TEXT PRIMARY KEY,count INTEGER NOT NULL,locked_until INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,action TEXT NOT NULL,subject TEXT NOT NULL,detail TEXT NOT NULL);
CREATE INDEX challenges_expiry ON challenges(expires);
CREATE INDEX replay_expiry ON replay(expires);
CREATE INDEX devices_license ON devices(license_id);
